385  processMSG(UA_Server *server, UA_SecureChannel *channel,
   386             UA_UInt32 requestId, const UA_ByteString *msg) {
   387      /* At 0, the nodeid starts... */
   388      size_t offset = 0;
   389
   390      /* Decode the nodeid */
   391      UA_NodeId requestTypeId;
   392      UA_StatusCode retval = UA_NodeId_decodeBinary(msg, &offset, &requestTypeId);
   393      if(retval != UA_STATUSCODE_GOOD)
   394          return retval;
   395      if(requestTypeId.namespaceIndex != 0 ||
   396         requestTypeId.identifierType != UA_NODEIDTYPE_NUMERIC)
   397          UA_NodeId_deleteMembers(&requestTypeId); /* leads to badserviceunsupported */
   398
   399      /* Store the start-position of the request */
   400      size_t requestPos = offset;
   401
   402      /* Get the service pointers */
   403      UA_Service service = NULL;
   404      const UA_DataType *requestType = NULL;
   405      const UA_DataType *responseType = NULL;
   406      UA_Boolean sessionRequired = true;
   407      UA_ServiceType serviceType = UA_SERVICETYPE_NORMAL;
   408      getServicePointers(requestTypeId.identifier.numeric, &requestType,
   409                         &responseType, &service, &sessionRequired, &serviceType);
   410      if(!requestType) {
   411          if(requestTypeId.identifier.numeric == 787) {
   412              UA_LOG_INFO_CHANNEL(server->config.logger, channel,
   413                                  "Client requested a subscription, " \
   414                                  "but those are not enabled in the build");
   415          } else {
   416              UA_LOG_INFO_CHANNEL(server->config.logger, channel,
   417                                  "Unknown request with type identifier %i",
   418                                  requestTypeId.identifier.numeric);
   419          }
   420          return sendServiceFault(channel, msg, requestPos, &UA_TYPES[UA_TYPES_SERVICEFAULT],
   421                                  requestId, UA_STATUSCODE_BADSERVICEUNSUPPORTED);
   422      }
   423      UA_assert(responseType);
   424
   425      /* Decode the request */
   426      void *request = UA_alloca(requestType->memSize);
   427      UA_RequestHeader *requestHeader = (UA_RequestHeader*)request;
   428      retval = UA_decodeBinary(msg, &offset, request, requestType,
   429                               server->config.customDataTypesSize,
   430                               server->config.customDataTypes);
   431      if(retval != UA_STATUSCODE_GOOD) {
   432          UA_LOG_DEBUG_CHANNEL(server->config.logger, channel,
   433                               "Could not decode the request");
   434          return sendServiceFault(channel, msg, requestPos, responseType, requestId, retval);
   435      }
   436
   437      /* Prepare the respone */
   438      void *response = UA_alloca(responseType->memSize);
   439      UA_init(response, responseType);
   440      UA_Session *session = NULL; /* must be initialized before goto send_response */
   441
   442      /* CreateSession doesn't need a session */
   443      if(requestType == &UA_TYPES[UA_TYPES_CREATESESSIONREQUEST]) {
   444          Service_CreateSession(server, channel,
   445              (const UA_CreateSessionRequest *)request,
   446                                (UA_CreateSessionResponse *)response);
   447          #ifdef FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION
   448          // store the authentication token and session ID so we can help fuzzing by setting
   449          // these values in the next request automatically
   450          UA_CreateSessionResponse *res = (UA_CreateSessionResponse *)response;
   451          UA_NodeId_copy(&res->authenticationToken, &unsafe_fuzz_authenticationToken);
   452          #endif
   453          goto send_response;
   454      }
   455
